        "title": "Luyện nghe bài 7: Forensic Linguistics & Discourse",
        "transcript": "Hello everyone! My name is Anna. I am 21 years old and I currently live in London. I am a university student studying languages. Today, I am very excited to share my experience with Forensic Linguistics & Discourse. In my daily routine, I frequently use the word \"Forensic linguistics\" when talking with friends. Yesterday afternoon, I spent one hour practicing \"Idiolect\" with my classmates. In addition, knowing how to use \"Authorship\" correctly helps me communicate much more naturally. I believe that practicing for fifteen minutes every day is the best secret to becoming confident. Thank you very much for listening!",
