        "title": "Luyện nghe bài 9: Native Idiomacity & Vernacular Nuances",
        "transcript": "Hello everyone! My name is Anna. I am 21 years old and I currently live in London. I am a university student studying languages. Today, I am very excited to share my experience with Native Idiomacity & Vernacular Nuances. In my daily routine, I frequently use the word \"Beyond the pale\" when talking with friends. Yesterday afternoon, I spent one hour practicing \"Fly in the ointment\" with my classmates. In addition, knowing how to use \"Bite the dust\" correctly helps me communicate much more naturally. I believe that practicing for fifteen minutes every day is the best secret to becoming confident. Thank you very much for listening!",
