        "explanation": "Diễn ngôn tinh hoa bản ngữ C2: Subtle Semantic Distinctions Between Near-Synonyms. Dạng khẳng định dùng để diễn đạt sự thật, thói quen hoặc thông tin cơ bản liên quan đến \"Subtle Semantic Distinctions Between Near-Synonyms\".",
